<?php
require __DIR__.'/includes/bootstrap.php';
$city=trim($_GET['ville']??'');$arrival=$_GET['arrivee']??'';$departure=$_GET['depart']??'';$people=max(1,(int)($_GET['personnes']??1));$budget=max(0,(int)($_GET['budget']??0));$stars=max(0,min(5,(int)($_GET['etoiles']??0)));
$sql="SELECT h.*,MIN(r.prix_nuit) prix_nuit,COALESCE(AVG(rv.note),0) note,COUNT(DISTINCT rv.id) avis FROM hotels h JOIN rooms r ON r.hotel_id=h.id AND r.disponible=1 LEFT JOIN reviews rv ON rv.hotel_id=h.id WHERE h.actif=1 AND r.capacite>=?";$args=[$people];if($city!==''){$sql.=' AND h.ville LIKE ?';$args[]='%'.$city.'%';}if($budget>0){$sql.=' AND r.prix_nuit<=?';$args[]=$budget;}if($stars){$sql.=' AND h.etoiles>=?';$args[]=$stars;}if($arrival&&$departure&&$arrival<$departure){$sql.=" AND EXISTS(SELECT 1 FROM rooms ar WHERE ar.hotel_id=h.id AND ar.disponible=1 AND ar.capacite>=? AND NOT EXISTS(SELECT 1 FROM room_bookings b WHERE b.room_id=ar.id AND b.statut IN ('en_attente','confirmee','payee') AND b.date_arrivee<? AND b.date_depart>?))";$args[]=$people;$args[]=$departure;$args[]=$arrival;}$sql.=' GROUP BY h.id ORDER BY h.etoiles DESC';$s=$pdo->prepare($sql);$s->execute($args);$hotels=$s->fetchAll();$found=count($hotels);$title='Hébergements au Cameroun';require __DIR__.'/includes/header.php';
?>
