      <div class="result-list"><?php foreach($hotels as $h):?><article class="stay-card"><img loading="lazy" src="<?=e($h['image_principale']?:'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80')?>" alt="Hôtel <?=e($h['nom'])?>"><div class="stay-content"><div><div class="flex gap-2 items-center"><h2 class="stay-title"><?=e($h['nom'])?></h2><span class="pill"><?=str_repeat('★',(int)$h['etoiles'])?></span></div><p class="stay-location">⌖ <?=e($h['ville'])?> · <?=e($h['adresse'])?></p><p class="stay-description"><?=e($h['description'])?></p><p class="stay-rate"><?php if($h['avis']):?><span class="pill"><?=number_format((float)$h['note'],1)?> / 5</span> · <?=$h['avis']?> avis<?php else:?>Hébergement partenaire Voyalo<?php endif;?></p></div><div class="stay-price"><small>À partir de</small><strong><?=money($h['prix_nuit'])?></strong><small>par nuit</small><a class="btn" href="/hotel-detail.php?id=<?=(int)$h['id']?>&arrivee=<?=e($arrival)?>&depart=<?=e($departure)?>&personnes=<?=$people?>">Voir les chambres</a></div></div></article><?php endforeach;?><?php if(!$hotels):?><div class="empty-state"><strong class="text-slate-800">Aucun hébergement trouvé</strong><p class="mt-2">Essayez d'autres dates ou élargissez votre budget.</p><a class="btn mt-4" href="/hotels.php">Effacer les filtres</a></div><?php endif;?></div>
